 */
var rotate = function(matrix) {
    const n = matrix.length;

    const flip = (r, c) => {
        //console.log('flipping', r, c);
        const temp = matrix[r][c];
        matrix[r][c] = matrix[n - 1 - c][r];                // 0,0 = 2,0 | 0,1 = 1,0
        matrix[n - 1 - c][r] = matrix[n - 1 - r][n - 1 - c];// 2,0 = 2,2 | 1,0 = 2,1
        matrix[n - 1 - r][n - 1 - c] = matrix[c][n - 1 - r];// 2,2 = 0,2 | 2,1 = 1,2
        matrix[c][n - 1 - r] = temp;                        // 0,2 = 0,0 | 1,2 = 0,1
        //console.log('flipped', matrix);
    };

    for (let i = 0; i < n - 1; i++) {
        for (let j = i; j < n - i - 1; j++) {
            flip(i, j);
        }
    }
};

